// Local replacement for BufferGeometryUtils.mergeGeometries.
// This keeps the game compatible with opening the HTML directly via file://.
function mergeGeometries(geometries, useGroups = false) {
  const valid = geometries.filter(Boolean);
  if (!valid.length) return new THREE.BufferGeometry();
  const attrs = ['position', 'normal', 'uv'];
  const out = new THREE.BufferGeometry();
  for (const name of attrs) {
    const first = valid[0].getAttribute(name);
    if (!first) continue;
    const arrays = [];
    let total = 0;
    for (const g of valid) {
      const ng = g.index ? g.toNonIndexed() : g;
      const a = ng.getAttribute(name);
      if (!a) continue;
      arrays.push(a.array);
      total += a.array.length;
    }
    const Ctor = first.array.constructor;
    const merged = new Ctor(total);
    let offset = 0;
    for (const arr of arrays) { merged.set(arr, offset); offset += arr.length; }
    out.setAttribute(name, new THREE.BufferAttribute(merged, first.itemSize, first.normalized));
  }
  return out;
}


