// Polígono perimetral: visualmente alargado, con seis/octogonalidad
// suave en las esquinas para que las gradas queden conectadas y sin huecos.
// Se conservan lados largos paralelos a la cancha y extremos recortados.
const CHAMFER_X = 9;
const CHAMFER_Z = 9;

const arenaPoints = [
  new THREE.Vector2(-FREE_HALF_W + CHAMFER_X,  FREE_HALF_L),
  new THREE.Vector2( FREE_HALF_W - CHAMFER_X,  FREE_HALF_L),
  new THREE.Vector2( FREE_HALF_W,              FREE_HALF_L - CHAMFER_Z),
  new THREE.Vector2( FREE_HALF_W,             -FREE_HALF_L + CHAMFER_Z),
  new THREE.Vector2( FREE_HALF_W - CHAMFER_X, -FREE_HALF_L),
  new THREE.Vector2(-FREE_HALF_W + CHAMFER_X, -FREE_HALF_L),
  new THREE.Vector2(-FREE_HALF_W,             -FREE_HALF_L + CHAMFER_Z),
  new THREE.Vector2(-FREE_HALF_W,              FREE_HALF_L - CHAMFER_Z)
];

function makeArenaShape(points) {
  const shape = new THREE.Shape();
  shape.moveTo(points[0].x, points[0].y);
  for (let i = 1; i < points.length; i++) shape.lineTo(points[i].x, points[i].y);
  shape.closePath();
  return shape;
}

