// Materiales del estadio.
const stadiumConcrete = new THREE.MeshToonMaterial({ color: 0x1b2230 });
const stadiumConcrete2 = new THREE.MeshToonMaterial({ color: 0x252d3c });
const stadiumDark = new THREE.MeshToonMaterial({ color: 0x080c14 });
const stadiumSeat = new THREE.MeshToonMaterial({ color: 0x0f1724 });
const stadiumSeat2 = new THREE.MeshToonMaterial({ color: 0x182235 });
const spectatorMat = new THREE.MeshToonMaterial({ color: 0x202a38 });
const spectatorAltMat = new THREE.MeshToonMaterial({ color: 0x303b4d });
