const bannerAccent = new THREE.MeshBasicMaterial({ color: 0x7b6aa8 });

// Buffers para fusionar geometría estática de las gradas (rendimiento):
// en vez de cientos de meshes individuales, terminamos con solo 3.
const mergedStepGeoA = [];
const mergedStepGeoB = [];
const mergedRailGeo = [];
// Objetos contra los que la cámara no debe atravesar (colisión de cámara).
const cameraColliders = [];

// Crea carteles con textura Canvas para mantener el estilo del arena.
function makeArenaBannerTexture(title, subtitle = "") {
  const c = document.createElement('canvas');
  c.width = 1024; c.height = 160;
  const g = c.getContext('2d');

  g.fillStyle = '#eeeaf6';
  g.fillRect(0, 0, c.width, c.height);

  g.fillStyle = '#8b78aa';
  g.fillRect(0, 0, c.width, 20);
  g.fillRect(0, c.height - 16, c.width, 16);

  g.fillStyle = '#2b2436';
  g.font = '900 46px sans-serif';
  g.textAlign = 'center';
  g.textBaseline = 'middle';
  g.fillText(title, c.width / 2, 67);

  if (subtitle) {
    g.fillStyle = '#5d536e';
    g.font = '700 21px sans-serif';
    g.fillText(subtitle, c.width / 2, 116);
  }

  return new THREE.CanvasTexture(c);
}

const ARENA_ROWS = 32;
const ROW_DEPTH = 0.62;
const ROW_HEIGHT = 0.47;

// Devuelve una normal hacia AFUERA del polígono.
// Así todas las gradas crecen radialmente y se encuentran en las esquinas.
function getOutwardNormal(a, b) {
  const dx = b.x - a.x;
  const dz = b.y - a.y;
  let nx = dz;
  let nz = -dx;
  const len = Math.hypot(nx, nz) || 1;
  nx /= len; nz /= len;

  const mx = (a.x + b.x) * 0.5;
  const mz = (a.y + b.y) * 0.5;

  // El centro está en 0,0. Si la normal apunta al centro, se invierte.
  if (nx * (-mx) + nz * (-mz) > 0) {
    nx = -nx;
    nz = -nz;
  }
  return { x: nx, z: nz };
}

function addPerimeterStand(a, b, edgeIndex) {
  const stand = new THREE.Group();

  const dx = b.x - a.x;
  const dz = b.y - a.y;
  const edgeLength = Math.hypot(dx, dz);
  const yaw = Math.atan2(-dz, dx);
  const normal = getOutwardNormal(a, b);

  // Un pequeño solape en las puntas evita cualquier hueco visual entre sectores.
  const sectionLength = edgeLength + 0.55;
  const seatsPerRow = Math.max(38, Math.floor(edgeLength / 0.30));
  const crowdCount = Math.floor(seatsPerRow * 0.80);

  for (let r = 0; r < ARENA_ROWS; r++) {
    const midX = (a.x + b.x) * 0.5 + normal.x * (r * ROW_DEPTH + ROW_DEPTH * 0.5);
    const midZ = (a.y + b.y) * 0.5 + normal.z * (r * ROW_DEPTH + ROW_DEPTH * 0.5);
    const y = 0.22 + r * ROW_HEIGHT;

    // Escalón: geometría fusionada al final (no se agrega mesh individual).
    const stepGeo = new THREE.BoxGeometry(sectionLength, ROW_HEIGHT, ROW_DEPTH + 0.07);
    const stepDummy = new THREE.Object3D();
    stepDummy.position.set(midX, y, midZ);
    stepDummy.rotation.y = yaw;
    stepDummy.updateMatrix();
    stepGeo.applyMatrix4(stepDummy.matrix);
    (r % 2 ? mergedStepGeoA : mergedStepGeoB).push(stepGeo);

    // Frente/baranda del escalón (también fusionada).
    const railGeo = new THREE.BoxGeometry(sectionLength, 0.045, 0.045);
    const railDummy = new THREE.Object3D();
    railDummy.position.set(
      (a.x + b.x) * 0.5 + normal.x * (r * ROW_DEPTH + 0.035),
      y + 0.22,
      (a.y + b.y) * 0.5 + normal.z * (r * ROW_DEPTH + 0.035)
    );
    railDummy.rotation.y = yaw;
    railDummy.updateMatrix();
    railGeo.applyMatrix4(railDummy.matrix);
    mergedRailGeo.push(railGeo);

    // Asientos.
    const seatGeo = new THREE.BoxGeometry(0.25, 0.16, 0.27);
    const seats = new THREE.InstancedMesh(
      seatGeo,
      (r + edgeIndex) % 2 ? stadiumSeat : stadiumSeat2,
      seatsPerRow
    );
    const dummy = new THREE.Object3D();

    for (let i = 0; i < seatsPerRow; i++) {
      const t = seatsPerRow === 1 ? 0.5 : i / (seatsPerRow - 1);
      const px = THREE.MathUtils.lerp(a.x, b.x, t);
      const pz = THREE.MathUtils.lerp(a.y, b.y, t);

      dummy.position.set(
        px + normal.x * (r * ROW_DEPTH + 0.16),
        y + 0.17,
        pz + normal.z * (r * ROW_DEPTH + 0.16)
      );
      dummy.rotation.y = yaw;
      dummy.updateMatrix();
      seats.setMatrixAt(i, dummy.matrix);
    }
    seats.instanceMatrix.needsUpdate = true;
    stand.add(seats);

    // Público.
    const crowdGeo = new THREE.SphereGeometry(0.11, 6, 5);
    const crowd = new THREE.InstancedMesh(
      crowdGeo,
      (r + edgeIndex) % 3 ? spectatorMat : spectatorAltMat,
      crowdCount
    );
    const crowdDummy = new THREE.Object3D();

    for (let i = 0; i < crowd.count; i++) {
      const seatIndex = (i * 7 + r * 13 + edgeIndex * 5) % seatsPerRow;
      const t = seatsPerRow === 1 ? 0.5 : seatIndex / (seatsPerRow - 1);
      const px = THREE.MathUtils.lerp(a.x, b.x, t);
      const pz = THREE.MathUtils.lerp(a.y, b.y, t);

      crowdDummy.position.set(
        px + normal.x * (r * ROW_DEPTH + 0.21),
        y + 0.34 + ((i + r + edgeIndex) % 3) * 0.018,
        pz + normal.z * (r * ROW_DEPTH + 0.21)
      );
      crowdDummy.rotation.y = yaw;
      crowdDummy.scale.set(
        1,
        1.15 + ((i + r) % 2) * 0.12,
        1
      );
      crowdDummy.updateMatrix();
      crowd.setMatrixAt(i, crowdDummy.matrix);
    }
    crowd.instanceMatrix.needsUpdate = true;
    stand.add(crowd);
  }

  const topY = 0.22 + ARENA_ROWS * ROW_HEIGHT;
  const mx = (a.x + b.x) * 0.5;
  const mz = (a.y + b.y) * 0.5;

  // Muro de seguridad FRONTAL de 1.50 m.
  // Sigue cada lado del nuevo perímetro y cierra completamente el acceso.
  const frontWall = new THREE.Mesh(
    new THREE.BoxGeometry(sectionLength, 1.5, 0.26),
    stadiumDark
  );
  frontWall.position.set(
    mx + normal.x * 0.13,
    0.75,
    mz + normal.z * 0.13
  );
  frontWall.rotation.y = yaw;
  frontWall.castShadow = true;
  frontWall.receiveShadow = true;
  stand.add(frontWall);
  cameraColliders.push(frontWall);

  // Muro exterior detrás de las gradas.
  const topWall = new THREE.Mesh(
    new THREE.BoxGeometry(sectionLength + 2, 5.5, 1.8),
    stadiumDark
  );
  topWall.position.set(
    mx + normal.x * (ARENA_ROWS * ROW_DEPTH + 1.0),
    topY + 2.75,
    mz + normal.z * (ARENA_ROWS * ROW_DEPTH + 1.0)
  );
  topWall.rotation.y = yaw;
  topWall.castShadow = true;
  stand.add(topWall);
  cameraColliders.push(topWall);

  // Carteles distribuidos en los lados principales.
  if (edgeIndex % 2 === 0) {
    const board = new THREE.Mesh(
      new THREE.PlaneGeometry(Math.min(13.5, Math.max(8.0, edgeLength * 0.52)), 2.1),
      new THREE.MeshBasicMaterial({
        map: makeArenaBannerTexture(
          edgeIndex === 0 || edgeIndex === 4 ? 'JUST VOLLEYBALL' : 'VOLLEYBALL',
          'CHAMPIONSHIP ARENA'
        ),
        side: THREE.DoubleSide
      })
    );

    board.position.set(
      mx + normal.x * (ARENA_ROWS * ROW_DEPTH + 0.13),
      topY - 1.8,
      mz + normal.z * (ARENA_ROWS * ROW_DEPTH + 0.13)
    );
    board.rotation.y = yaw + Math.PI;
    stand.add(board);
  }

  stadiumGroup.add(stand);
}

// Las 8 secciones forman un perímetro continuo, con las esquinas cerradas
// y una silueta alargada tipo hexágono/octágono.
for (let i = 0; i < arenaPoints.length; i++) {
  const a = arenaPoints[i];
  const b = arenaPoints[(i + 1) % arenaPoints.length];
  addPerimeterStand(a, b, i);
}

// Relleno de las 8 esquinas: conecta cada tramo de grada con el siguiente
// sin dejar huecos visibles entre sectores.
function addCornerSeatFill(vertexIndex) {
  const v = arenaPoints[vertexIndex];
  const prev = arenaPoints[(vertexIndex - 1 + arenaPoints.length) % arenaPoints.length];
  const next = arenaPoints[(vertexIndex + 1) % arenaPoints.length];
  const nPrev = getOutwardNormal(prev, v);
  const nNext = getOutwardNormal(v, next);

  let bx = nPrev.x + nNext.x;
  let bz = nPrev.z + nNext.z;
  const len = Math.hypot(bx, bz) || 1;
  bx /= len;
  bz /= len;

  const yaw = Math.atan2(bx, bz);
  const size = ROW_DEPTH * 1.55;

  for (let r = 0; r < ARENA_ROWS; r++) {
    const centerDist = r * ROW_DEPTH + ROW_DEPTH * 0.52;

    const connGeo = new THREE.BoxGeometry(size, ROW_HEIGHT, size);
    const connDummy = new THREE.Object3D();
    connDummy.position.set(
      v.x + bx * centerDist,
      0.22 + r * ROW_HEIGHT,
      v.y + bz * centerDist
    );
    connDummy.rotation.y = yaw;
    connDummy.updateMatrix();
    connGeo.applyMatrix4(connDummy.matrix);
    (r % 2 ? mergedStepGeoB : mergedStepGeoA).push(connGeo);
  }
}

for (let i = 0; i < arenaPoints.length; i++) {
  addCornerSeatFill(i);
}

// Fusiona toda la geometría estática de las gradas en 3 meshes en vez de
// cientos, para bajar drásticamente los drawcalls y mejorar el rendimiento.
function finalizeStadiumGeometry() {
  if (mergedStepGeoA.length) {
    const geo = mergeGeometries(mergedStepGeoA, false);
    const mesh = new THREE.Mesh(geo, stadiumConcrete);
    mesh.castShadow = true; mesh.receiveShadow = true;
    stadiumGroup.add(mesh);
    cameraColliders.push(mesh);
  }
  if (mergedStepGeoB.length) {
    const geo = mergeGeometries(mergedStepGeoB, false);
    const mesh = new THREE.Mesh(geo, stadiumConcrete2);
    mesh.castShadow = true; mesh.receiveShadow = true;
    stadiumGroup.add(mesh);
    cameraColliders.push(mesh);
  }
  if (mergedRailGeo.length) {
    const geo = mergeGeometries(mergedRailGeo, false);
    const mesh = new THREE.Mesh(geo, stadiumRail);
    stadiumGroup.add(mesh);
  }
}
finalizeStadiumGeometry();

// El perímetro de la zona libre no lleva una línea visible.
// Así la textura teal queda limpia alrededor de la cancha; las únicas líneas visibles
// en el piso son las líneas reglamentarias de la cancha definidas arriba.

// Mantén al jugador dentro del área libre de 9 m, siguiendo el perímetro.
// Se deja un pequeño margen para que el radio del personaje no atraviese el muro.
function clampPointToArenaPolygon(entity, margin = PLAYER_R + 0.06) {
  // Varias pasadas permiten resolver correctamente las esquinas.
  for (let pass = 0; pass < 4; pass++) {
    for (let i = 0; i < arenaPoints.length; i++) {
      const a = arenaPoints[i];
      const b = arenaPoints[(i + 1) % arenaPoints.length];
      const n = getOutwardNormal(a, b);

      const mx = (a.x + b.x) * 0.5;
      const mz = (a.y + b.y) * 0.5;

      // Permitimos estar hasta "margin" hacia fuera; si se supera,
      // lo devolvemos hacia dentro del polígono.
      const signed = n.x * (entity.x - mx) + n.z * (entity.z - mz);
      if (signed > -margin) {
        const push = signed + margin;
        entity.x -= n.x * push;
        entity.z -= n.z * push;
      }
    }
  }
  // La zona jugable sigue estando del lado local del jugador.
  entity.x = Math.max(-FREE_HALF_W + margin, Math.min(FREE_HALF_W - margin, entity.x));
  entity.z = Math.max(-FREE_HALF_L + margin, Math.min(FREE_HALF_L - margin, entity.z));
}

