function createCharacter(opts) {
  const root = new THREE.Group();
  const skinMat = new THREE.MeshToonMaterial({ color: opts.skinColor ?? 0xffd7b0 });
  const bodyMat = new THREE.MeshToonMaterial({ color: opts.bodyColor });
  const accentMat = new THREE.MeshToonMaterial({ color: opts.accentColor ?? opts.bodyColor });
  const hairMat = new THREE.MeshToonMaterial({ color: opts.hairColor });
  const shortsMat = new THREE.MeshToonMaterial({ color: opts.shortsColor ?? 0x334155 });
  const shoeMat = new THREE.MeshToonMaterial({ color: opts.shoeColor ?? 0x1f2937 });

  const torsoPivot = new THREE.Group(); torsoPivot.position.y = 0.95; root.add(torsoPivot);
  const torso = new THREE.Mesh(new THREE.CapsuleGeometry(0.24, 0.5, 4, 10), bodyMat);
  torso.position.y = 0.28; torso.castShadow = true; torsoPivot.add(torso);

  // Detalle del uniforme: permite diferenciar jugadores sin cambiar el modelo base.
  const jerseyBand = new THREE.Mesh(new THREE.CylinderGeometry(0.245, 0.245, 0.10, 12), accentMat);
  jerseyBand.position.y = 0.12; jerseyBand.castShadow = true; torsoPivot.add(jerseyBand);

  const headPivot = new THREE.Group(); headPivot.position.y = 0.78; torsoPivot.add(headPivot);
  const head = new THREE.Mesh(new THREE.SphereGeometry(0.27, 18, 14), skinMat);
  head.position.y = 0.18; head.castShadow = true; headPivot.add(head);
  const hair = new THREE.Mesh(new THREE.SphereGeometry(0.29, 18, 14, 0, Math.PI * 2, 0, Math.PI * 0.6), hairMat);
  hair.position.y = 0.20; headPivot.add(hair);

  // Vincha configurable por personaje.
  const headbandMat = new THREE.MeshToonMaterial({ color: opts.headbandColor ?? opts.accentColor ?? opts.bodyColor });
  const headband = new THREE.Mesh(new THREE.TorusGeometry(0.275, 0.035, 8, 24), headbandMat);
  headband.rotation.x = Math.PI / 2;
  headband.position.y = 0.20;
  headband.scale.y = 0.82;
  headPivot.add(headband);

  const nose = new THREE.Mesh(new THREE.SphereGeometry(0.07, 8, 6), skinMat); nose.position.set(0, 0.15, -0.26); headPivot.add(nose);
  const eyeMat = new THREE.MeshBasicMaterial({ color: 0x111827 });
  const eyeL = new THREE.Mesh(new THREE.SphereGeometry(0.04, 6, 5), eyeMat); eyeL.position.set(-0.09, 0.20, -0.24); headPivot.add(eyeL);
  const eyeR = eyeL.clone(); eyeR.position.x = 0.09; headPivot.add(eyeR);

  const armLPivot = new THREE.Group(); armLPivot.position.set(-0.30, 0.55, 0); torsoPivot.add(armLPivot);
  const upperArmL = new THREE.Mesh(new THREE.CapsuleGeometry(0.075, 0.32, 3, 8), bodyMat); upperArmL.position.y = -0.18; upperArmL.castShadow = true; armLPivot.add(upperArmL);
  const forearmLPivot = new THREE.Group(); forearmLPivot.position.y = -0.36; armLPivot.add(forearmLPivot);
  const forearmL = new THREE.Mesh(new THREE.CapsuleGeometry(0.065, 0.30, 3, 8), skinMat); forearmL.position.y = -0.17; forearmL.castShadow = true; forearmLPivot.add(forearmL);
  const handL = new THREE.Mesh(new THREE.SphereGeometry(0.10, 8, 7), skinMat); handL.position.y = -0.36; forearmLPivot.add(handL);

  const armRPivot = new THREE.Group(); armRPivot.position.set(0.30, 0.55, 0); torsoPivot.add(armRPivot);
  const upperArmR = new THREE.Mesh(new THREE.CapsuleGeometry(0.075, 0.32, 3, 8), bodyMat); upperArmR.position.y = -0.18; upperArmR.castShadow = true; armRPivot.add(upperArmR);
  const forearmRPivot = new THREE.Group(); forearmRPivot.position.y = -0.36; armRPivot.add(forearmRPivot);
  const forearmR = new THREE.Mesh(new THREE.CapsuleGeometry(0.065, 0.30, 3, 8), skinMat); forearmR.position.y = -0.17; forearmR.castShadow = true; forearmRPivot.add(forearmR);
  const handR = new THREE.Mesh(new THREE.SphereGeometry(0.10, 8, 7), skinMat); handR.position.y = -0.36; forearmRPivot.add(handR);

  const legLPivot = new THREE.Group(); legLPivot.position.set(-0.13, 0, 0); root.add(legLPivot);
  const thighL = new THREE.Mesh(new THREE.CapsuleGeometry(0.10, 0.34, 3, 8), shortsMat); thighL.position.y = -0.20; thighL.castShadow = true; legLPivot.add(thighL);
  const shinLPivot = new THREE.Group(); shinLPivot.position.y = -0.42; legLPivot.add(shinLPivot);
  const shinL = new THREE.Mesh(new THREE.CapsuleGeometry(0.085, 0.32, 3, 8), shortsMat); shinL.position.y = -0.18; shinL.castShadow = true; shinLPivot.add(shinL);
  const footL = new THREE.Mesh(new THREE.BoxGeometry(0.20, 0.10, 0.34), shoeMat); footL.position.set(0, -0.38, -0.06); footL.castShadow = true; shinLPivot.add(footL);

  const legRPivot = new THREE.Group(); legRPivot.position.set(0.13, 0, 0); root.add(legRPivot);
  const thighR = new THREE.Mesh(new THREE.CapsuleGeometry(0.10, 0.34, 3, 8), shortsMat); thighR.position.y = -0.20; thighR.castShadow = true; legRPivot.add(thighR);
  const shinRPivot = new THREE.Group(); shinRPivot.position.y = -0.42; legRPivot.add(shinRPivot);
  const shinR = new THREE.Mesh(new THREE.CapsuleGeometry(0.085, 0.32, 3, 8), shortsMat); shinR.position.y = -0.18; shinR.castShadow = true; shinRPivot.add(shinR);
  const footR = new THREE.Mesh(new THREE.BoxGeometry(0.20, 0.10, 0.34), shoeMat); footR.position.set(0, -0.38, -0.06); footR.castShadow = true; shinRPivot.add(footR);

  // Nuevo Anillo de Selección (Toon Style)
  const ringColor = (opts.team === 'home') ? 0x00ffcc : 0xff33cc;
  const ring = new THREE.Mesh(
    new THREE.RingGeometry(0.55, 0.70, 32),
    new THREE.MeshBasicMaterial({ color: ringColor, side: THREE.DoubleSide, transparent: true, opacity: 0.9 })
  );
  ring.rotation.x = -Math.PI / 2; ring.position.y = 0.04; root.add(ring);

  return { root, torsoPivot, headPivot, armLPivot, armRPivot, forearmLPivot, forearmRPivot, legLPivot, legRPivot, shinLPivot, shinRPivot, ring, headband };
}


// ============================================================
// PERSONAJES 3D — rig real + RunFast + respiración retargeteada
// ============================================================
const characterAssets = {
  loaded: false,
  scene: null,
  runClip: null,
  idleClip: null
};

const characterBoneAliases = {
  hips:'Hips', spine:'Spine', spine1:'Spine01', spine01:'Spine01', spine2:'Spine02', spine02:'Spine02',
  neck:'neck', head:'Head', leftshoulder:'LeftShoulder', leftarm:'LeftArm', leftforearm:'LeftForeArm',
  leftupperarm:'LeftArm', lefthand:'LeftHand', leftfingerbase:'LeftHand_End',
  rightshoulder:'RightShoulder', rightarm:'RightArm', rightforearm:'RightForeArm', rightupperarm:'RightArm',
  righthand:'RightHand', rightfingerbase:'RightHand_End', leftupleg:'LeftUpLeg', leftleg:'LeftLeg',
  leftfoot:'LeftFoot', lefttoebase:'LeftToeBase', lefttoe:'LeftToeBase', rightupleg:'RightUpLeg',
  rightleg:'RightLeg', rightfoot:'RightFoot', righttoebase:'RightToeBase', righttoe:'RightToeBase'
};
function normalizeBoneName(raw) {
  return String(raw).replace(/^mixamorig[:_]?/i,'').replace(/^mixamorig/i,'').replace(/[^a-zA-Z0-9]/g,'').toLowerCase();
}
function findCharacterBone(name, bones) {
  const k = normalizeBoneName(name);
  const alias = characterBoneAliases[k];
  if (alias && bones.has(alias)) return bones.get(alias);
  for (const [boneName,bone] of bones) if (normalizeBoneName(boneName) === k) return bone;
  return null;
}
function buildRelativeQuaternionTrack(src, targetBone) {
  const vals = src.values, times = src.times, n = times.length;
  if (vals.length !== n * 4) return null;
  const q0 = new THREE.Quaternion(vals[0], vals[1], vals[2], vals[3]).normalize();
  const inv0 = q0.clone().invert();
  const base = targetBone.quaternion.clone();
  const out = new Float32Array(vals.length);
  for (let i=0;i<n;i++) {
    const q = new THREE.Quaternion(vals[i*4],vals[i*4+1],vals[i*4+2],vals[i*4+3]).normalize();
    const delta = q.clone().multiply(inv0);
    const result = base.clone().multiply(delta).normalize();
    out[i*4]=result.x; out[i*4+1]=result.y; out[i*4+2]=result.z; out[i*4+3]=result.w;
  }
  return new THREE.QuaternionKeyframeTrack(targetBone.name+'.quaternion', times.slice(), out);
}

class CharacterVisual3D {
  constructor(entity, sourceScene, runClip, idleClip) {
    this.entity = entity;
    this.root = new THREE.Group();
    this.root.name = 'Player3D_' + entity.team + (entity.isPlayer ? '_human' : '_bot');
    this.model = SkeletonUtils.clone(sourceScene);
    this.root.add(this.model);
    scene.add(this.root);

    this.model.traverse(o => {
      if (o.isMesh) { o.castShadow = true; o.receiveShadow = true; }
    });
    // El GLB base mide 1.70 m en su geometría. No usamos Box3 de un SkinnedMesh
    // porque puede incluir la pose/esqueleto y dar una escala incorrecta.
    const SOURCE_MODEL_H = 1.70;
    const scale = VISUAL_PLAYER_H / SOURCE_MODEL_H;
    this.model.scale.setScalar(scale);
    // Corrección visual: el asset mira al eje opuesto al forward del juego.
    // Se corrige aquí sin cambiar la orientación lógica/physics del jugador.
    this.model.rotation.y = Math.PI;
    const box2 = new THREE.Box3().setFromObject(this.model);
    this.model.position.y -= box2.min.y;

    this.bones = new Map();
    this.model.traverse(o => { if (o.isBone) this.bones.set(o.name, o); });
    this.base = new Map();
    for (const [name,bone] of this.bones) {
      this.base.set(name, {
        q: bone.quaternion.clone(),
        p: bone.position.clone(),
        s: bone.scale.clone()
      });
    }

    const ringColor = entity.team === 'home' ? 0x00ffcc : 0xff33cc;
    this.ring = new THREE.Mesh(
      new THREE.RingGeometry(0.55,0.70,32),
      new THREE.MeshBasicMaterial({color:ringColor,side:THREE.DoubleSide,transparent:true,opacity:0.9})
    );
    this.ring.rotation.x = -Math.PI/2; this.ring.position.y = 0.04; this.root.add(this.ring);

    this.mixer = new THREE.AnimationMixer(this.model);
    this.runAction = runClip ? this.mixer.clipAction(runClip) : null;
    this.idleAction = idleClip ? this.mixer.clipAction(idleClip) : null;
    for (const a of [this.runAction, this.idleAction]) {
      if (a) { a.setLoop(THREE.LoopRepeat, Infinity); a.enabled = false; }
    }
    this.mode = 'idle';
    this.runSpeed = 1;
    this.lastMoving = false;
    this.poseMode = 'idle';
    this.poseDuration = 0.4;
    this.setMode('idle');
  }
  resetPose() {
    for (const [name,bone] of this.bones) {
      const b = this.base.get(name); if (!b) continue;
      bone.quaternion.copy(b.q); bone.position.copy(b.p); bone.scale.copy(b.s);
    }
  }
  stopActions() {
    if (this.runAction) { this.runAction.stop(); this.runAction.enabled=false; }
    if (this.idleAction) { this.idleAction.stop(); this.idleAction.enabled=false; }
    this.resetPose();
  }
  setIdleClip(idleClip) {
    if (!idleClip || this.idleAction) return;
    this.idleAction = this.mixer.clipAction(idleClip);
    this.idleAction.setLoop(THREE.LoopRepeat, Infinity);
    this.idleAction.enabled = false;
    if (this.mode === 'idle') this.setMode('idle', this.runSpeed, true);
  }

  setMode(mode, speed=1, force=false) {
    if (!force && this.mode === mode && Math.abs(this.runSpeed-speed) < 0.03) return;
    this.mode = mode; this.runSpeed = speed;
    this.stopActions();
    if (mode === 'run' && this.runAction) {
      this.runAction.reset(); this.runAction.enabled=true; this.runAction.timeScale=speed; this.runAction.play();
    } else if (mode === 'idle' && this.idleAction) {
      this.idleAction.reset(); this.idleAction.enabled=true; this.idleAction.timeScale=1; this.idleAction.play();
    }
  }
  bone(name) { return this.bones.get(name); }
  baseQ(name) { return this.base.get(name)?.q; }
  deltaEuler(name, x=0,y=0,z=0) {
    const bone=this.bone(name), base=this.baseQ(name); if(!bone||!base) return;
    const d=new THREE.Quaternion().setFromEuler(new THREE.Euler(x,y,z,'XYZ'));
    bone.quaternion.copy(base).multiply(d).normalize();
  }
  updateActionPose(action, t) {
    const u=Math.max(0,Math.min(1,t));
    const wave=Math.sin(u*Math.PI);
    const smooth=u*u*(3-2*u);
    if(action==='jump' || action==='jumpstart') {
      const prep=Math.sin(Math.min(1,u*1.8)*Math.PI/2);
      this.deltaEuler('Spine', -0.08*prep,0,0);
      this.deltaEuler('Spine01', -0.16*prep,0,0);
      this.deltaEuler('Spine02', -0.18*prep,0,0);
      this.deltaEuler('LeftArm', -1.0*prep,0.05,0.08);
      this.deltaEuler('RightArm', -1.0*prep,-0.05,-0.08);
      this.deltaEuler('LeftForeArm', -0.35*prep,0,0);
      this.deltaEuler('RightForeArm', -0.35*prep,0,0);
      this.deltaEuler('LeftUpLeg', 0.55*prep,0,0);
      this.deltaEuler('RightUpLeg', 0.55*prep,0,0);
      this.deltaEuler('LeftLeg', -0.75*prep,0,0);
      this.deltaEuler('RightLeg', -0.75*prep,0,0);
    } else if(action==='spike') {
      const prep=u<0.42 ? u/0.42 : 1;
      const snap=u<0.42 ? 0 : (u-0.42)/0.58;
      this.deltaEuler('Spine', 0.16*wave,0,0);
      this.deltaEuler('Spine01', 0.25*wave,0,0);
      this.deltaEuler('Spine02', 0.22*wave,0,0);
      this.deltaEuler('LeftArm', -1.0*wave,0.0,0.1*wave);
      this.deltaEuler('LeftForeArm', -0.35*wave,0,0);
      this.deltaEuler('RightArm', -2.0*prep + 3.1*snap*wave,0.0,-0.12*wave);
      this.deltaEuler('RightForeArm', -0.65*snap*wave,0,0);
      this.deltaEuler('LeftUpLeg', -0.25*wave,0,0);
      this.deltaEuler('RightUpLeg', -0.30*wave,0,0);
    } else if(action==='receive') {
      this.deltaEuler('Spine', 0.18*wave,0,0);
      this.deltaEuler('Spine01', 0.32*wave,0,0);
      this.deltaEuler('Spine02', 0.18*wave,0,0);
      this.deltaEuler('LeftArm', -0.75*wave,0.15*wave,0.05);
      this.deltaEuler('RightArm', -0.75*wave,-0.15*wave,-0.05);
      this.deltaEuler('LeftForeArm', 0.10*wave,0,0);
      this.deltaEuler('RightForeArm', 0.10*wave,0,0);
      this.deltaEuler('LeftUpLeg', 0.45*wave,0,0);
      this.deltaEuler('RightUpLeg', 0.45*wave,0,0);
      this.deltaEuler('LeftLeg', -0.55*wave,0,0);
      this.deltaEuler('RightLeg', -0.55*wave,0,0);
    } else if(action==='set') {
      this.deltaEuler('Spine01', -0.12*wave,0,0);
      this.deltaEuler('Spine02', -0.12*wave,0,0);
      this.deltaEuler('LeftArm', -1.55*wave,0.12*wave,0.15*wave);
      this.deltaEuler('RightArm', -1.55*wave,-0.12*wave,-0.15*wave);
      this.deltaEuler('LeftForeArm', -0.85*wave,0,0);
      this.deltaEuler('RightForeArm', -0.85*wave,0,0);
    } else if(action==='block') {
      this.deltaEuler('Spine', -0.18*wave,0,0);
      this.deltaEuler('Spine01', -0.22*wave,0,0);
      this.deltaEuler('LeftArm', -1.85*wave,0.08*wave,0.12*wave);
      this.deltaEuler('RightArm', -1.85*wave,-0.08*wave,-0.12*wave);
      this.deltaEuler('LeftForeArm', -0.55*wave,0,0);
      this.deltaEuler('RightForeArm', -0.55*wave,0,0);
    } else if(action==='land') {
      const squash=wave;
      this.deltaEuler('Spine',0.16*squash,0,0);
      this.deltaEuler('Spine01',0.22*squash,0,0);
      this.deltaEuler('LeftUpLeg',0.30*squash,0,0);
      this.deltaEuler('RightUpLeg',0.30*squash,0,0);
      this.deltaEuler('LeftLeg',-0.38*squash,0,0);
      this.deltaEuler('RightLeg',-0.38*squash,0,0);
    }
  }
  applyBreathing(dt) {
    // Respiración visible y sutil: se aplica DESPUÉS del mixer para que
    // ningún clip idle pueda ocultarla. No modifica posición ni hitbox.
    this.breathTime = (this.breathTime || 0) + dt;
    const phase = this.breathTime * 1.65;
    const inhale = (Math.sin(phase) + 1) * 0.5;
    const smooth = inhale * inhale * (3 - 2 * inhale);

    const spine = this.bone('Spine');
    const spine01 = this.bone('Spine01');
    const spine02 = this.bone('Spine02');
    const neck = this.bone('neck');

    // Movimiento torácico más perceptible (aprox. 2–6 grados).
    if (spine) this.deltaEuler('Spine', 0.018 * smooth, 0, 0);
    if (spine01) this.deltaEuler('Spine01', -0.055 * smooth, 0, 0);
    if (spine02) this.deltaEuler('Spine02', -0.085 * smooth, 0, 0);
    if (neck) this.deltaEuler('neck', 0.028 * smooth, 0, 0);

    // Expansión mínima del pecho para que la respiración sea visible incluso
    // con cámara alejada, sin deformar el personaje.
    const chest = spine02 || spine01 || spine;
    if (chest) {
      const b = this.base.get(chest.name);
      if (b) {
        chest.scale.copy(b.s);
        const expand = 1 + 0.022 * smooth;
        chest.scale.x *= expand;
        chest.scale.z *= expand;
      }
    }
  }
  update(dt, entity, moving, sprintFactor) {
    let mode;
    if (entity.diveTime > 0) mode='receive';
    else if (entity.action && entity.actionTime > 0) mode=entity.action==='jumpstart'?'jumpstart':entity.action;
    else if (!entity.onGround) mode='jump';
    else if (moving) mode='run';
    else mode='idle';

    if (mode !== this.poseMode) {
      this.poseMode = mode;
      this.poseDuration = mode === 'jumpstart' ? 0.16 : Math.max(0.16, entity.actionTime || 0.4);
    }

    if (mode==='run') this.setMode('run', sprintFactor ? 1.12 : 0.78);
    else if (mode==='idle') this.setMode('idle');
    else this.stopActions();

    if (mode==='run' || mode==='idle') {
      if (this.mixer) this.mixer.update(dt);
      if (mode === 'idle') this.applyBreathing(dt);
    } else {
      const progress = entity.action && entity.actionTime > 0
        ? 1 - Math.max(0, entity.actionTime / this.poseDuration)
        : Math.min(1, (entity.airTime || 0) / 0.28);
      this.updateActionPose(mode, progress);
    }

    if (entity.actionTime > 0) {
      entity.actionTime -= dt;
      if (entity.actionTime <= 0) entity.action=null;
    }

    const s=entity.diveTime>0 ? 1.25 : 1;
    this.ring.scale.x += (s-this.ring.scale.x)*Math.min(1,dt*12);
    this.ring.scale.z += (s-this.ring.scale.z)*Math.min(1,dt*12);
    if (entity.diveTime<=0) {
      this.ring.scale.x += (1-this.ring.scale.x)*0.15;
      this.ring.scale.z += (1-this.ring.scale.z)*0.15;
    }
  }
}

async function init3DCharacters() {
  try {
    const gltf = await new GLTFLoader().loadAsync('characters/player_base_rigged.glb');
    characterAssets.scene = gltf.scene;
    characterAssets.runClip = gltf.animations?.find(a => a.name === 'RunFast') || gltf.animations?.[0] || null;

    // Respiración: el FBX usa nombres Mixamo; se retargetea a los huesos del GLB
    // manteniendo la pose base del personaje. Si el FBX falla, el juego sigue funcionando.
    try {
      const fbx = await new FBXLoader().loadAsync('characters/respiracion.fbx');
      const src = fbx.animations?.[0];
      if (src) {
        const refModel = SkeletonUtils.clone(gltf.scene);
        const bones = new Map();
        refModel.traverse(o => { if (o.isBone) bones.set(o.name, o); });
        const tracks = [];
        for (const tr of src.tracks) {
          const dot = tr.name.lastIndexOf('.');
          if (dot < 1 || tr.name.slice(dot + 1) !== 'quaternion') continue;
          const target = findCharacterBone(tr.name.slice(0, dot), bones);
          if (!target) continue;
          const rt = buildRelativeQuaternionTrack(tr, target);
          if (rt) tracks.push(rt);
        }
        if (tracks.length) {
          characterAssets.idleClip = new THREE.AnimationClip('Idle_Breathing', src.duration, tracks);
        }
      }
      console.log('Respiracion cargada:', !!characterAssets.idleClip);
    } catch (idleErr) {
      characterAssets.idleClip = null;
      console.warn('Respiracion no disponible; se mantiene idle estático.', idleErr);
    }

    characterAssets.loaded = true;
    for (const e of allEntities) e.attach3DCharacter();
    console.log('Personajes 3D cargados:', {run:!!characterAssets.runClip, idle:!!characterAssets.idleClip});
  } catch(err) {
    console.error('No se pudo cargar el modelo 3D:', err);
  }
}

class Entity {
  constructor(opts) {
    this.x = opts.x; this.y = 0; this.z = opts.z;
    this.vy = 0;
    this.team = opts.team;
    this.isPlayer = !!opts.isPlayer;
    this.radius = PLAYER_R; this.height = PLAYER_H;
    this.onGround = true;
    this.hitCooldown = 0;
    this.diveTime = 0; this.diveCooldown = 0;
    this.diveDirX = 0; this.diveDirZ = 0;
    this.facingYaw = this.team === 'home' ? 0 : Math.PI;
    this.targetFacingYaw = this.facingYaw;
    this.walkPhase = Math.random() * 6.28; this.airTime = 0;
    this.stepTimer = 0;
    this.wasMoving = false;
    // Estado de movimiento de la IA: evita micro-paradas cuando el objetivo cambia
    // constantemente cerca del punto de destino.
    this.aiMoving = false;
    this.moveTime = 0;
    this.moveStopCooldown = 0;
    
    this.action = null; 
    this.actionTime = 0;

    this.mesh = new THREE.Group();
    this.mesh.name = 'PlayerPlaceholder';
    this.mesh.position.set(this.x, 0, this.z);
    this.mesh.rotation.y = this.facingYaw;
    scene.add(this.mesh);
    this.visual3D = null;

    this.homeX = opts.x; this.homeZ = opts.z;
  }
  attach3DCharacter() {
    if (this.visual3D || !characterAssets.loaded) return;
    scene.remove(this.mesh);
    this.visual3D = new CharacterVisual3D(this, characterAssets.scene, characterAssets.runClip, characterAssets.idleClip);
    this.mesh = this.visual3D.root;
    this.mesh.position.set(this.x,this.y,this.z);
    this.mesh.rotation.y=this.facingYaw;
  }
  sync() {
    this.mesh.position.set(this.x, this.y, this.z);
    this.mesh.rotation.y = this.facingYaw;
  }
  jump() {
    if (!this.onGround || this.diveTime > 0) return false;
    if (this.wasMoving) SFX.moveStop();
    this.vy = 8.8; this.onGround = false; this.airTime = 0;
    this.action = 'jumpstart'; this.actionTime = 0.16;
    return true;
  }
  dive(dirX, dirZ) {
    if (!this.onGround || this.diveTime > 0 || this.diveCooldown > 0) return false;
    let len = Math.hypot(dirX, dirZ);
    if (len < 0.1) { dirX = -Math.sin(this.facingYaw); dirZ = -Math.cos(this.facingYaw); len = 1; }
    this.diveDirX = dirX / len; this.diveDirZ = dirZ / len;
    this.diveTime = DIVE_DURATION; this.diveCooldown = DIVE_COOLDOWN;
    emitDust(this.x, this.z, 5);
    return true;
  }
  canHit(ball, forgive = 0) {
    const diveBoost = this.diveTime > 0 ? DIVE_REACH : 1.0;
    const hitR = (this.radius + ball.radius + 0.7 + forgive) * diveBoost;
    const dx = ball.x - this.x; const dz = ball.z - this.z;
    if (dx * dx + dz * dz > hitR * hitR) return false;
    const lowReach = this.diveTime > 0 ? 1.8 : 0.25;
    const highReach = this.height + (this.onGround ? 0.7 : 1.4) + forgive;
    return ball.y >= this.y - ball.radius - lowReach && ball.y <= this.y + highReach + ball.radius;
  }

  // Hitbox ampliada EXCLUSIVA para el remate en el aire.
  // Esto evita que el toque normal se vuelva demasiado fácil.
  canSpike(ball, forgive = SPIKE_HIT_FORGIVENESS) {
    const hitR = SPIKE_HIT_RADIUS + forgive + ball.radius;
    const dx = ball.x - this.x; const dz = ball.z - this.z;
    if (dx * dx + dz * dz > hitR * hitR) return false;
    const lowReach = this.diveTime > 0 ? 1.9 : 0.2;
    const highReach = this.height + 1.4 + SPIKE_VERTICAL_EXTRA + forgive;
    return ball.y >= this.y - ball.radius - lowReach && ball.y <= this.y + highReach + ball.radius;
  }
  updateVisual(dt, moving, sprintFactor = 0) {
    let diff = this.targetFacingYaw - this.facingYaw;
    while (diff > Math.PI) diff -= Math.PI * 2;
    while (diff < -Math.PI) diff += Math.PI * 2;
    this.facingYaw += diff * Math.min(1, dt * 14);
    if (this.visual3D) this.visual3D.update(dt, this, moving, sprintFactor);
  }
  update(dt, moving, sprintFactor = 0) {
    if (!this.onGround) {
      this.vy -= GRAVITY * dt; this.y += this.vy * dt; this.airTime += dt;
      if (this.y <= 0) {
        this.y = 0; this.vy = 0; this.onGround = true; this.airTime = 0;
        this.action = 'land'; this.actionTime = 0.22;
        emitDust(this.x, this.z, 4);
      }
    }
    if (this.diveTime > 0) {
      this.diveTime -= dt;
      this.x += this.diveDirX * DIVE_SPEED * dt; this.z += this.diveDirZ * DIVE_SPEED * dt;
    }
    if (this.hitCooldown > 0) this.hitCooldown -= dt;
    if (this.diveCooldown > 0) this.diveCooldown -= dt;

    if (this.isPlayer) {
      this.x = Math.max(-25, Math.min(25, this.x)); 
      this.z = Math.max(0.1, Math.min(30, this.z)); 
    } else {
      this.x = Math.max(-H_COURT + 0.3, Math.min(H_COURT - 0.3, this.x));
      if (this.team === 'home') this.z = Math.max(0.6, Math.min(H_LEN - 0.2, this.z));
      else this.z = Math.max(-H_LEN + 0.2, Math.min(-0.6, this.z));
    }

    if (moving && this.onGround && this.diveTime <= 0) {
      this.stepTimer -= dt;
      if (this.stepTimer <= 0) {
        emitDust(this.x, this.z, 2);
        this.stepTimer = sprintFactor > 0 ? 0.14 : 0.22;
      }
    }

    // El sonido de suelo solo se dispara tras un movimiento real y continuo.
    // Esto evita que pequeñas oscilaciones de la IA generen muchos rechinidos.
    if (this.moveStopCooldown > 0) this.moveStopCooldown -= dt;
    if (moving) {
      this.moveTime += dt;
    } else {
      if (this.wasMoving && this.moveTime >= 0.18 && this.moveStopCooldown <= 0) {
        SFX.moveStop();
        this.moveStopCooldown = 0.28;
      }
      this.moveTime = 0;
    }
    this.wasMoving = moving;
    this.updateVisual(dt, moving, sprintFactor);
    this.sync();
  }
}

class Ball {
  constructor() {
    this.x = 0; this.y = 3; this.z = 5;
    this.vx = 0; this.vy = 0; this.vz = 0;
    this.radius = BALL_R;
    this.lastHit = null;
    this.lastHitTeam = null;
    this.activeTeam = null;
    this.teamTouches = 0;

    const group = new THREE.Group();
    // Material Toon
    const sphere = new THREE.Mesh(new THREE.SphereGeometry(BALL_R, 20, 16), new THREE.MeshToonMaterial({ color: 0xfbbf24 }));
    sphere.castShadow = true; group.add(sphere);
    const stripe = new THREE.Mesh(new THREE.TorusGeometry(BALL_R * 0.99, BALL_R * 0.15, 6, 22), new THREE.MeshToonMaterial({ color: 0x1e3a8a }));
    stripe.rotation.x = Math.PI / 2; group.add(stripe);
    const stripe2 = stripe.clone(); stripe2.rotation.set(0, 0, Math.PI / 2); group.add(stripe2);
    this.mesh = group; scene.add(this.mesh);
  }
  sync() {
    this.mesh.position.set(this.x, this.y, this.z);
    this.mesh.rotation.x += this.vz * 0.03; this.mesh.rotation.z -= this.vx * 0.03;
  }
  update(dt) {
    const speed = Math.hypot(this.vx, this.vy, this.vz);
    const steps = Math.max(1, Math.ceil(speed * dt / 0.1));
    const sdt = dt / steps;
    for (let i = 0; i < steps; i++) if (this.step(sdt)) return 'landed';
    return null;
  }
  step(dt) {
    const px = this.x, py = this.y, pz = this.z;
    this.vy -= GRAVITY * dt;
    this.x += this.vx * dt; this.y += this.vy * dt; this.z += this.vz * dt;
    this.checkNet(px, py, pz);
    if (this.y - this.radius <= 0 && this.vy < 0) { this.y = this.radius; return true; }
    return false;
  }
  checkNet(px, py, pz) {
    const d0 = pz, d1 = this.z;
    if (d0 * d1 >= 0) return;
    const t = d0 / (d0 - d1);
    const xc = px + t * (this.x - px);
    const yc = py + t * (this.y - py);
    if (Math.abs(xc) > H_COURT + 0.4) return;
    if (yc >= NET_H + this.radius) return;
    if (yc < 0) return;
    this.z = d0 > 0 ? 0.08 : -0.08; this.x = xc; this.y = yc;
    this.vz *= -0.22; this.vx *= 0.35; this.vy *= 0.4;
    SFX.net();
  }
}

